/**
 * AI DAILY NEWS REPORTER - FEED REGISTRY
 * ---------------------------------------------------------------------------
 * Define approved RSS sources and their fallback editorial categories.
 */

const feeds = [
  {
    id: 'scmp-china',
    name: 'South China Morning Post',
    sourceCategory: 'china',
    url: 'https://www.scmp.com/rss/91/feed',
  },
  {
    id: 'lemonde-france-politics',
    name: 'Le Monde — French Politics',
    sourceCategory: 'france',
    url: 'https://www.lemonde.fr/en/politics/rss_full.xml',
  },
  {
    id: 'nyt-us',
    name: 'The New York Times — U.S.',
    sourceCategory: 'us',
    url: 'https://rss.nytimes.com/services/xml/rss/nyt/US.xml',
  },
  {
    id: 'cnbc-business',
    name: 'CNBC — Business',
    sourceCategory: 'business',
    url: 'https://search.cnbc.com/rs/search/combinedcms/view.xml?partnerId=wrss01&id=10000664',
  },
  {
    id: 'techcrunch-technology',
    name: 'TechCrunch',
    sourceCategory: 'technology',
    url: 'https://techcrunch.com/feed/',
  },
  {
    id: 'wired-ai',
    name: 'WIRED — AI',
    sourceCategory: 'ai',
    url: 'https://www.wired.com/feed/tag/ai/latest/rss',
  },
  {
    id: 'bbc-world',
    name: 'BBC News — World',
    sourceCategory: 'world',
    url: 'https://feeds.bbci.co.uk/news/world/rss.xml',
  },
];

return feeds.map((feed) => ({ json: feed }));

/**
 * AI DAILY NEWS REPORTER - ATTACH FEED METADATA
 * ---------------------------------------------------------------------------
 * Restore source identity and normalize feed health for every RSS item.
 */

const sources = $('Load Feed Sources').all().map((item) => item.json);
const groupedEntries = Array.from({ length: sources.length }, () => []);
const sourceIndexById = new Map(sources.map((source, index) => [source.id, index]));
const inputEntries = $input.all();

for (let inputIndex = 0; inputIndex < inputEntries.length; inputIndex++) {
  const item = inputEntries[inputIndex];
  let source;
  try {
    // Resolve the feed that produced this RSS item.
    source = $('Load Feed Sources').itemMatching(inputIndex).json;
  } catch (error) {
    const raw = item?.json || {};
    if (raw.title || raw.link || raw.guid || raw.error) {
      throw new Error('RSS output lost its source pairing; refusing to attach incorrect metadata.');
    }
    continue;
  }

  const sourceIndex = sourceIndexById.get(source?.id);
  if (!Number.isInteger(sourceIndex)) {
    throw new Error('RSS output matched an unknown feed source.');
  }
  groupedEntries[sourceIndex].push(item);
}

const output = [];

for (let index = 0; index < sources.length; index++) {
  const source = sources[index];
  const entries = groupedEntries[index];
  const base = {
    sourceId: source.id,
    sourceName: source.name,
    sourceCategory: source.sourceCategory,
    sourceUrl: source.url,
  };

  const errorEntry = entries.find((item) => item?.json?.error);
  if (errorEntry) {
    const message = String(errorEntry.json.error?.message || errorEntry.json.error || 'Unknown RSS error')
      .replace(/\s+/g, ' ')
      .trim()
      .slice(0, 240);

    console.warn(`[feed] ${source.id}: fetch failed`);
    output.push({
      json: {
        ...base,
        _feedStatus: 'error',
        feedError: message,
      },
    });
    continue;
  }

  const articleEntries = entries.filter((item) => {
    const raw = item?.json || {};
    return Boolean(raw.title || raw.link || raw.guid || raw.isoDate || raw.pubDate);
  });

  if (articleEntries.length === 0) {
    console.warn(`[feed] ${source.id}: no entries`);
    output.push({ json: { ...base, _feedStatus: 'empty' } });
    continue;
  }

  console.log(`[feed] ${source.id}: ${articleEntries.length} raw entries`);
  output.push(...articleEntries.map((item) => ({
    json: {
      ...item.json,
      ...base,
      _feedStatus: 'ok',
    },
  })));
}

return output;

/**
 * AI DAILY NEWS REPORTER - NORMALIZE AND FILTER ARTICLES
 * ---------------------------------------------------------------------------
 * Validate feed health, sanitize RSS fields, enforce quality gates, remove exact
 * duplicates, and assign editorial categories.
 */

const cfg = $('Configuration').first().json;
const configuredFeeds = $('Load Feed Sources').all().map((item) => item.json);
const now = Date.now();
const cutoffMs = now - cfg.lookbackHours * 60 * 60 * 1000;
const futureLimitMs = now + cfg.futureToleranceMinutes * 60 * 1000;

const CATEGORY_LABELS = {
  china: '🇨🇳 Çin Gündemi',
  france: '🇫🇷 Fransa Gündemi',
  us: '🇺🇸 ABD Gündemi',
  asia: '🌏 Asya Gündemi',
  business: '💰 Ekonomi & Finans',
  technology: '💻 Teknoloji',
  ai: '🤖 Yapay Zeka',
  world: '🌍 Dünya Gündemi',
};

const NOISE_URL = /\/(sport|sports|style|fashion|food|travel|obituaries|crossword|crosswords|games|puzzles|lifestyle|entertainment|showbiz|shopping|deals|horoscope|video|videos|in-pictures|picture-gallery|audio|podcasts)(?:\/|$)/i;
const NOISE_TITLE = /^(watch|listen|video|photos|pictures|gallery|quiz|live updates|photo gallery|wordle|daily puzzle|recipe|horoscope|in pictures|audio)\b\s*[:\-—]?/i;
const TRACKING_PARAMETERS = new Set(['fbclid', 'gclid', 'mc_cid', 'mc_eid', 'ref_src', 'ref_url']);

const NAMED_ENTITIES = {
  '&amp;': '&',
  '&lt;': '<',
  '&gt;': '>',
  '&quot;': '"',
  '&apos;': "'",
  '&#39;': "'",
  '&nbsp;': ' ',
};

function decodeEntities(value) {
  return String(value ?? '')
    .replace(/&#x([0-9a-f]+);/gi, (_, code) => String.fromCodePoint(Number.parseInt(code, 16)))
    .replace(/&#(\d+);/g, (_, code) => String.fromCodePoint(Number(code)))
    .replace(/&(?:amp|lt|gt|quot|apos|nbsp);/g, (match) => NAMED_ENTITIES[match] ?? ' ');
}

function toPlainText(value) {
  return decodeEntities(String(value ?? '').replace(/<[^>]*>/g, ' '))
    .replace(/\s+/g, ' ')
    .trim();
}

function trimToWord(text, maxLength) {
  if (text.length <= maxLength) return text;
  const cut = text.slice(0, maxLength);
  const lastSpace = cut.lastIndexOf(' ');
  const boundary = lastSpace > maxLength * 0.6 ? lastSpace : maxLength;
  return `${cut.slice(0, boundary).trim()}…`;
}

function parseHttpUrl(rawUrl) {
  const value = String(rawUrl || '').trim();
  const match = value.match(/^(https?):\/\/([^\/?#]+)([^?#]*)(?:\?([^#]*))?(?:#.*)?$/i);
  if (!match || match[2].includes('@')) return null;

  const protocol = match[1].toLowerCase();
  const authority = match[2].toLowerCase().replace(/^www\./, '');
  const hostname = authority.replace(/:\d+$/, '');
  const pathname = (match[3] || '/')
    .replace(/\/{2,}/g, '/')
    .replace(/\/$/, '') || '/';

  const queryParts = (match[4] || '')
    .split('&')
    .filter(Boolean)
    .filter((part) => {
      const encodedKey = part.split('=', 1)[0];
      let key = encodedKey;
      try {
        key = decodeURIComponent(encodedKey);
      } catch {
        // Keep the original key if a publisher sends malformed percent-encoding.
      }
      key = key.toLowerCase();
      return !key.startsWith('utm_') && !TRACKING_PARAMETERS.has(key);
    })
    .sort();

  const query = queryParts.length ? `?${queryParts.join('&')}` : '';
  return {
    href: `${protocol}://${authority}${pathname}${query}`,
    hostname,
    pathname,
  };
}

function titleKey(title) {
  return title
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function resolveCategory(raw, url, title, snippet) {
  const probe = `${url.pathname} ${title} ${snippet}`.toLowerCase();

  const rules = [
    ['france', /\b(france|french|macron|assemblée nationale|elysée)\b|\/en\/(?:politics|france)\//i],
    ['china', /\b(china|chinese|beijing|hong kong)\b|\/(?:china|hong-kong)\//i],
    ['asia', /\b(asia|asian|asia-pacific|india|indian|pakistan|pakistani|bangladesh|bangladeshi|sri lanka|sri lankan|nepal|nepalese|bhutan|maldives|afghanistan|afghan|japan|japanese|south korea|north korea|korean|taiwan|taiwanese|mongolia|mongolian|indonesia|indonesian|malaysia|malaysian|singapore|singaporean|thailand|thai|vietnam|vietnamese|philippines|filipino|myanmar|cambodia|cambodian|laos|laotian|southeast asia|south asia|east asia)\b|\/(?:week-asia|asia|south-asia|southeast-asia|east-asia)\//i],
    ['us', /\b(united states|u\.s\.|american|white house|congress|federal reserve|trump|washington)\b|\/(?:us|united-states)\//i],
    ['world', /\/(?:world|europe|middle-east|africa)\//i],
    ['ai', /\b(artificial intelligence|openai|chatgpt|gemini|large language model|llm|machine learning|deepmind|anthropic|yapay zeka)\b/i],
    ['technology', /\b(technology|software|cybersecurity|semiconductor|microchip|startup|data cent(?:er|re)|smartphone|cloud computing|robotics)\b/i],
    ['business', /\b(economy|economic|inflation|central bank|interest rate|stock market|earnings|finance|banking|tariff|trade deal|revenue)\b/i],
  ];

  const matched = rules.find(([, pattern]) => pattern.test(probe));
  if (matched) return matched[0];
  return CATEGORY_LABELS[raw.sourceCategory] ? raw.sourceCategory : 'world';
}

const feedState = new Map(configuredFeeds.map((feed) => [feed.id, {
  id: feed.id,
  name: feed.name,
  status: 'missing',
  error: '',
}]));

for (const item of $input.all()) {
  const raw = item.json || {};
  if (!raw.sourceId || !feedState.has(raw.sourceId)) continue;
  const state = feedState.get(raw.sourceId);
  if (raw._feedStatus === 'error') {
    state.status = 'error';
    state.error = String(raw.feedError || 'RSS fetch failed').slice(0, 240);
  } else if (raw._feedStatus === 'ok') {
    state.status = 'ok';
  } else if (raw._feedStatus === 'empty' && state.status === 'missing') {
    state.status = 'empty';
  }
}

const feedHealth = [...feedState.values()];
const healthySources = feedHealth.filter(({ status }) => status === 'ok' || status === 'empty').length;
const failedSources = feedHealth.filter(({ status }) => status === 'error' || status === 'missing');

if (healthySources < cfg.minHealthySources) {
  throw new Error(`Feed health gate failed: ${healthySources}/${configuredFeeds.length} sources are healthy.`);
}

const stats = {
  configuredSources: configuredFeeds.length,
  healthySources,
  failedSources,
  totalIncoming: 0,
  kept: 0,
  skippedInvalid: 0,
  skippedNoDate: 0,
  skippedTooOld: 0,
  skippedFuture: 0,
  skippedDuplicate: 0,
  skippedNoise: 0,
  skippedQuota: 0,
};

const seenUrls = new Set();
const seenTitles = new Set();
const perSource = {};
const articles = [];

for (const item of $input.all()) {
  const raw = item.json || {};
  if (raw._feedStatus !== 'ok') continue;
  stats.totalIncoming++;

  const rawLink = [raw.link, raw.link?._, raw.guid, raw.guid?._]
    .find((value) => typeof value === 'string' && /^https?:\/\//i.test(value.trim()));
  const parsedUrl = parseHttpUrl(rawLink);
  const link = parsedUrl?.href || '';
  const title = toPlainText(raw.title);

  if (!link || title.length < cfg.minTitleLength) {
    stats.skippedInvalid++;
    continue;
  }

  const publishedMs = Date.parse(raw.isoDate || raw.pubDate || raw.date || '');
  if (!Number.isFinite(publishedMs)) {
    stats.skippedNoDate++;
    continue;
  }
  if (publishedMs < cutoffMs) {
    stats.skippedTooOld++;
    continue;
  }
  if (publishedMs > futureLimitMs) {
    stats.skippedFuture++;
    continue;
  }

  const nameKey = titleKey(title);
  if (seenUrls.has(link) || seenTitles.has(nameKey)) {
    stats.skippedDuplicate++;
    continue;
  }
  if (NOISE_URL.test(parsedUrl.pathname) || NOISE_TITLE.test(title)) {
    stats.skippedNoise++;
    continue;
  }

  const sourceId = raw.sourceId || parsedUrl.hostname;
  perSource[sourceId] = (perSource[sourceId] || 0) + 1;
  if (perSource[sourceId] > cfg.maxArticlesPerSource) {
    stats.skippedQuota++;
    continue;
  }

  const body = toPlainText(raw.contentSnippet || raw.content || raw.description || '');
  const snippet = trimToWord(body, cfg.snippetLength);
  const category = resolveCategory(raw, parsedUrl, title, snippet);

  seenUrls.add(link);
  seenTitles.add(nameKey);
  articles.push({
    id: `a${articles.length}`,
    title,
    link,
    snippet,
    category,
    categoryLabel: CATEGORY_LABELS[category],
    sourceId,
    source: raw.sourceName || parsedUrl.hostname,
    sourceDomain: parsedUrl.hostname,
    publishedAt: new Date(publishedMs).toISOString(),
  });
}

stats.kept = articles.length;
stats.sourcesWithArticles = Object.keys(perSource).length;

console.log('[normalize]', JSON.stringify(stats));
return [{ json: { articles, stats } }];

/**
 * AI DAILY NEWS REPORTER - BUILD SCORING BATCHES
 * ---------------------------------------------------------------------------
 * Distribute normalized articles across a bounded number of balanced LLM
 * calls while retaining a complete ID-to-article lookup.
 */

const cfg = $('Configuration').first().json;
const input = $input.first().json;
const articles = Array.isArray(input.articles) ? input.articles : [];
const articlesById = Object.fromEntries(articles.map((article) => [article.id, article]));

if (articles.length === 0) {
  return [{
    json: {
      batchIndex: 0,
      batchCount: 1,
      articleCount: 0,
      articlesById,
      ingestionStats: input.stats || {},
      payload: [],
    },
  }];
}

const batchCount = Math.min(
  Math.max(1, Number(cfg.targetBatchCount) || 1),
  articles.length,
);
const groups = new Map();

for (const article of articles) {
  const category = article.category || 'world';
  if (!groups.has(category)) groups.set(category, []);
  groups.get(category).push(article);
}

for (const group of groups.values()) {
  group.sort((left, right) => Date.parse(right.publishedAt) - Date.parse(left.publishedAt));
}

const buckets = Array.from({ length: batchCount }, () => []);
const categories = [...groups.keys()].sort();
const cursors = new Map(categories.map((category) => [category, 0]));
let bucketIndex = 0;
let added = true;

while (added) {
  added = false;
  for (const category of categories) {
    const cursor = cursors.get(category);
    const group = groups.get(category);
    if (cursor >= group.length) continue;

    buckets[bucketIndex % batchCount].push(group[cursor]);
    cursors.set(category, cursor + 1);
    bucketIndex++;
    added = true;
  }
}

console.log(`[batches] ${articles.length} articles across ${batchCount} scoring calls`);
return buckets.map((batch, index) => ({
  json: {
    batchIndex: index,
    batchCount,
    articleCount: articles.length,
    articlesById,
    ingestionStats: input.stats || {},
    payload: batch.map(({ id, category, source, publishedAt, title, snippet }) => ({
      id,
      category,
      source,
      publishedAt,
      title,
      snippet,
    })),
  },
}));

/**
 * AI DAILY NEWS REPORTER - VALIDATE, RANK, AND SELECT
 * ---------------------------------------------------------------------------
 * Validate every model score and select a balanced running order under
 * category and source limits.
 */

const cfg = $('Configuration').first().json;
const batchDefinitions = $('Build Scoring Batches').all().map((item) => item.json);
const modelOutputs = $input.all();
const firstBatch = batchDefinitions[0] || {};
const articlesById = firstBatch.articlesById || {};
const ingestionStats = firstBatch.ingestionStats || {};

function parseJsonArray(value) {
  if (Array.isArray(value)) return value;
  const text = String(value ?? '').trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '');
  const parsed = JSON.parse(text);
  if (!Array.isArray(parsed)) throw new TypeError('Model output is not a JSON array.');
  return parsed;
}

function validateRow(row, expectedIds, seenIds, batchIndex) {
  if (!row || typeof row !== 'object' || Array.isArray(row)) {
    throw new TypeError(`Batch ${batchIndex}: score row must be an object.`);
  }
  if (typeof row.id !== 'string' || !expectedIds.has(row.id)) {
    throw new TypeError(`Batch ${batchIndex}: unknown or invalid article id.`);
  }
  if (seenIds.has(row.id)) {
    throw new TypeError(`Batch ${batchIndex}: duplicate article id ${row.id}.`);
  }
  if (!Number.isInteger(row.score) || row.score < 1 || row.score > 10) {
    throw new TypeError(`Batch ${batchIndex}: ${row.id} has an invalid integer score.`);
  }
  if (typeof row.reason !== 'string' || !row.reason.trim() || row.reason.length > 180) {
    throw new TypeError(`Batch ${batchIndex}: ${row.id} has an invalid reason.`);
  }
}

if (modelOutputs.length !== batchDefinitions.length) {
  throw new Error(`Scoring output count mismatch: expected ${batchDefinitions.length}, received ${modelOutputs.length}.`);
}

const scored = new Map();
let expectedTotal = 0;

for (let index = 0; index < batchDefinitions.length; index++) {
  const definition = batchDefinitions[index];
  const expectedIds = new Set((definition.payload || []).map(({ id }) => id));
  const output = modelOutputs[index]?.json?.output
    ?? modelOutputs[index]?.json?.text
    ?? modelOutputs[index]?.json?.response
    ?? modelOutputs[index]?.json?.message?.content
    ?? '';
  const rows = parseJsonArray(output);
  const seenIds = new Set();
  expectedTotal += expectedIds.size;

  for (const row of rows) {
    validateRow(row, expectedIds, seenIds, index);
    seenIds.add(row.id);
    scored.set(row.id, {
      score: row.score,
      reason: row.reason.trim(),
    });
  }

  const missingIds = [...expectedIds].filter((id) => !seenIds.has(id));
  if (missingIds.length > 0) {
    throw new Error(`Batch ${index}: model omitted ${missingIds.length} article id(s).`);
  }
}

const scoringCoverage = expectedTotal === 0 ? 1 : scored.size / expectedTotal;
if (scoringCoverage < cfg.minScoringCoverage) {
  throw new Error(`Scoring coverage gate failed: ${(scoringCoverage * 100).toFixed(1)}%.`);
}

const byImportance = (left, right) =>
  right.score - left.score || Date.parse(right.publishedAt) - Date.parse(left.publishedAt);
const candidates = [...scored.entries()]
  .map(([id, verdict]) => ({ ...articlesById[id], ...verdict }))
  .filter((article) => article.id)
  .sort(byImportance);

const selected = [];
const chosenIds = new Set();
const perCategory = {};
const perSource = {};

function canSelect(article) {
  if (chosenIds.has(article.id)) return false;
  if ((perCategory[article.category] || 0) >= cfg.maxPerCategory) return false;
  if ((perSource[article.sourceId] || 0) >= cfg.maxPerSource) return false;
  return true;
}

function select(article) {
  selected.push(article);
  chosenIds.add(article.id);
  perCategory[article.category] = (perCategory[article.category] || 0) + 1;
  perSource[article.sourceId] = (perSource[article.sourceId] || 0) + 1;
}

// Pass 1: the strongest eligible article from every represented category.
for (const article of candidates) {
  if (selected.length >= cfg.maxHeadlines) break;
  if (perCategory[article.category]) continue;
  if (article.score < cfg.categoryLeaderMinScore) continue;
  if (canSelect(article)) select(article);
}

// Pass 2: score-ranked fill under source and category caps.
for (const article of candidates) {
  if (selected.length >= cfg.maxHeadlines) break;
  if (article.score < cfg.fillMinScore) continue;
  if (canSelect(article)) select(article);
}

selected.sort(byImportance);
if (selected.length < cfg.minHeadlines) {
  throw new Error(`Editorial gate failed: selected ${selected.length}/${cfg.minHeadlines} required headlines.`);
}

const stats = {
  ...ingestionStats,
  batchesExecuted: modelOutputs.length,
  scoringCoverage,
  scored: scored.size,
  candidates: candidates.length,
  categoriesRepresented: Object.keys(perCategory).length,
  sourcesRepresented: Object.keys(perSource).length,
  selected: selected.length,
  selectedPerCategory: perCategory,
  selectedPerSource: perSource,
};

console.log('[selection]', JSON.stringify(stats));
return [{
  json: {
    selected,
    stats,
    forSummary: selected.map(({ id, title, snippet, categoryLabel, source, publishedAt }) => ({
      id,
      title,
      snippet,
      category: categoryLabel,
      source,
      publishedAt,
    })),
  },
}];

/**
 * AI DAILY NEWS REPORTER - VALIDATE COPY AND RENDER NEWSLETTER
 * ---------------------------------------------------------------------------
 * Validate generated Turkish copy and render equivalent HTML and plain-text email bodies.
 */

const cfg = $('Configuration').first().json;
const selection = $('Rank & Select Headlines').first().json;
const stories = selection.selected || [];
const stats = selection.stats || {};

const COLORS = {
  page: '#f1f5f9',
  card: '#ffffff',
  brand: '#059669',
  brandDark: '#047857',
  brandTint: '#d1fae5',
  text: '#1f2937',
  muted: '#64748b',
  border: '#e2e8f0',
  warningBackground: '#fff7ed',
  warningText: '#9a3412',
};

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function safeUrl(value) {
  const url = String(value ?? '').trim();
  return /^https?:\/\//i.test(url) ? escapeHtml(url) : '#';
}

function parseJsonArray(value) {
  if (Array.isArray(value)) return value;
  const text = String(value ?? '').trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '');
  const parsed = JSON.parse(text);
  if (!Array.isArray(parsed)) throw new TypeError('Summary output is not a JSON array.');
  return parsed;
}

function wordCount(value) {
  const text = String(value ?? '').trim();
  return text ? text.split(/\s+/u).length : 0;
}

function validateSummary(row, story) {
  if (!row || typeof row !== 'object' || Array.isArray(row)) {
    throw new TypeError('Every summary row must be an object.');
  }

  const title = typeof row.title === 'string' ? row.title.trim() : '';
  const summary = typeof row.summary === 'string' ? row.summary.trim() : '';
  const titleWords = wordCount(title);
  const summaryWords = wordCount(summary);

  if (
    title.length < 12
    || title.length > 180
    || titleWords < 8
    || titleWords > 16
    || /[\r\n]/.test(title)
    || /\p{Extended_Pictographic}/u.test(title)
  ) {
    throw new TypeError(`${story.id}: generated title violates editorial format limits.`);
  }
  if (summary.length < 20 || summary.length > 700 || summaryWords > 70) {
    throw new TypeError(`${story.id}: generated summary violates editorial format limits.`);
  }
}

if (stories.length === 0) {
  throw new Error('Delivery stopped: no headlines passed the editorial gate.');
}

const output = $input.first().json.output
  ?? $input.first().json.text
  ?? $input.first().json.response
  ?? $input.first().json.message?.content
  ?? '';
const rows = parseJsonArray(output);
const expectedIds = new Set(stories.map(({ id }) => id));
const summaries = new Map();

for (const row of rows) {
  if (typeof row?.id !== 'string' || !expectedIds.has(row.id)) {
    throw new TypeError('Summary output contains an unknown or invalid article id.');
  }
  if (summaries.has(row.id)) throw new TypeError(`Summary output duplicated ${row.id}.`);
  const story = stories.find(({ id }) => id === row.id);
  validateSummary(row, story);
  summaries.set(row.id, { title: row.title.trim(), summary: row.summary.trim() });
}

const missingIds = [...expectedIds].filter((id) => !summaries.has(id));
if (missingIds.length > 0) {
  throw new Error(`Summary output omitted ${missingIds.length} selected article(s).`);
}

const now = new Date();
const issueDate = now.toLocaleDateString(cfg.locale, {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric',
  timeZone: cfg.timeZone,
});
function formatTimestamp(iso) {
  return new Date(iso).toLocaleString(cfg.locale, {
    day: '2-digit',
    month: 'short',
    hour: '2-digit',
    minute: '2-digit',
    timeZone: cfg.timeZone,
  });
}

function renderStory(story, index) {
  const summary = summaries.get(story.id);
  const url = safeUrl(story.link);
  return `
      <tr>
        <td style="padding:0 0 16px 0;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="${COLORS.card}" style="background-color:${COLORS.card};border:1px solid ${COLORS.border};border-left:4px solid ${COLORS.brand};border-radius:10px;">
            <tr><td style="padding:20px 22px;">
              <p style="margin:0 0 10px;font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:${COLORS.brandDark};">${escapeHtml(story.categoryLabel)}</p>
              <h2 style="margin:0 0 10px;font-size:18px;line-height:1.35;font-weight:700;"><a href="${url}" target="_blank" rel="noopener noreferrer" style="color:${COLORS.text};text-decoration:none;">${escapeHtml(summary.title)}</a></h2>
              <p style="margin:0 0 18px;font-size:14.5px;line-height:1.6;color:${COLORS.text};">${escapeHtml(summary.summary)}</p>
              <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>
                <td align="left" style="font-size:12px;color:${COLORS.muted};">${index + 1} &middot; ${escapeHtml(story.source)} &middot; ${escapeHtml(formatTimestamp(story.publishedAt))} &middot; <strong style="color:${COLORS.brandDark};">${story.score}/10</strong></td>
                <td align="right"><a href="${url}" target="_blank" rel="noopener noreferrer" bgcolor="${COLORS.brand}" style="display:inline-block;background-color:${COLORS.brand};color:#fff;font-size:13px;font-weight:700;padding:9px 16px;border-radius:6px;text-decoration:none;">Haberi oku</a></td>
              </tr></table>
            </td></tr>
          </table>
        </td>
      </tr>`;
}

const failedSources = Array.isArray(stats.failedSources) ? stats.failedSources : [];
const warning = failedSources.length === 0 ? '' : `
      <tr><td bgcolor="${COLORS.warningBackground}" style="padding:12px 16px;border:1px solid #fed7aa;border-radius:8px;color:${COLORS.warningText};font-size:12px;line-height:1.5;">
        Kaynak uyarısı: ${escapeHtml(failedSources.map(({ name }) => name).join(', '))} bu sayıya veri sağlayamadı.
      </td></tr>
      <tr><td style="height:16px;font-size:0;line-height:16px;">&nbsp;</td></tr>`;

const subject = `${cfg.subjectPrefix} · ${issueDate}`;
const preheader = summaries.get(stories[0].id).title;
const cards = stories.map(renderStory).join('');
const html = `<!doctype html>
<html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(subject)}</title></head>
<body style="margin:0;padding:0;background-color:${COLORS.page};">
  <div style="display:none;max-height:0;overflow:hidden;opacity:0;">${escapeHtml(preheader)}</div>
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="${COLORS.page}"><tr><td align="center" style="padding:24px 12px;">
    <table role="presentation" width="680" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:680px;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;">
      <tr><td bgcolor="${COLORS.brand}" style="background-color:${COLORS.brand};border-radius:10px;padding:28px 24px;text-align:center;"><h1 style="margin:0 0 6px;font-size:25px;font-weight:800;color:#fff;">${escapeHtml(cfg.headerTitle)}</h1><p style="margin:0;font-size:14px;font-weight:600;color:${COLORS.brandTint};">${escapeHtml(issueDate)}</p></td></tr>
      <tr><td style="height:24px;font-size:0;line-height:24px;">&nbsp;</td></tr>
      ${warning}
      ${cards}
      <tr><td style="padding:18px 8px 0;border-top:1px solid ${COLORS.border};text-align:center;"><p style="margin:0;font-size:12px;color:${COLORS.muted};">${stats.totalIncoming || 0} haber tarandı &rarr; ${stats.scored || 0} analiz edildi &rarr; ${stories.length} seçildi</p></td></tr>
    </table>
  </td></tr></table>
</body></html>`;

const text = [
  `${cfg.headerTitle} — ${issueDate}`,
  failedSources.length ? `Kaynak uyarısı: ${failedSources.map(({ name }) => name).join(', ')}` : '',
  '',
  ...stories.map((story, index) => {
    const summary = summaries.get(story.id);
    return `${index + 1}. [${story.categoryLabel}] ${summary.title} (${story.score}/10)\n${summary.summary}\n${story.link}\n`;
  }),
  `${stats.totalIncoming || 0} haber tarandı; ${stats.scored || 0} analiz edildi; ${stories.length} haber seçildi.`,
].filter(Boolean).join('\n');

return [{
  json: {
    subject,
    html,
    text,
    storyCount: stories.length,
    deliveryStats: stats,
  },
}];
